1	package net.officefloor.hq.app.person;
2	
3	import java.sql.PreparedStatement;
4	import java.sql.Statement;
5	import java.util.List;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.jdbc.core.RowMapper;
8	import org.springframework.jdbc.support.GeneratedKeyHolder;
9	import org.springframework.stereotype.Repository;
10	
11	/** The person store, kept per sheet. */
12	@Repository
13	public class People {
14	
15	    private static final RowMapper<Person> ROW = (rs, i) -> {
16	        Person person = new Person(rs.getLong("id"),
17	                rs.getString("sheet_id"), rs.getString("name"), rs.getString("grade"), rs.getInt("version"));
18	        person.setStatementCount(rs.getInt("statement_count"));
19	        int terms = rs.getInt("terms");
20	        person.setTerms(rs.wasNull() ? null : terms);
21	        person.setContact(rs.getString("contact"));
22	        person.setStatedTotal(rs.getBigDecimal("stated_total"));
23	        java.sql.Date stated = rs.getDate("statement_date");
24	        person.setStatementDate(stated == null ? null : stated.toLocalDate());
25	        java.sql.Date retired = rs.getDate("retired_from");
26	        person.setRetiredFrom(retired == null ? null : retired.toLocalDate());
27	        java.sql.Date added = rs.getDate("added_on");
28	        person.setAddedOn(added == null ? null : added.toLocalDate());
29	        return person;
30	    };
31	
32	    /** Patron names sorted without regard to case, then by case. */
33	    private static final java.util.Comparator<String> BY_NAME =
34	            String.CASE_INSENSITIVE_ORDER.thenComparing(java.util.Comparator.naturalOrder());
35	
36	    private final JdbcTemplate jdbc;
37	    private final net.officefloor.hq.app.sheet.Sheets sheets;
38	
39	    public People(JdbcTemplate jdbc, net.officefloor.hq.app.sheet.Sheets sheets) {
40	        this.jdbc = jdbc;
41	        this.sheets = sheets;
42	    }
43	
44	    /** Fills in each person's holds, in the order they were added. */
45	    private List<Person> withHolds(String sheetId, List<Person> found) {
46	        if (found.isEmpty()) {
47	            return found;
48	        }
49	        java.util.Map<Long, java.util.List<Person.Hold>> holds = new java.util.HashMap<>();
50	        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY seq", rs -> {
51	            java.sql.Date to = rs.getDate("to_date");
52	            holds.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.ArrayList<>())
53	                    .add(new Person.Hold(rs.getDate("from_date").toLocalDate(), to == null ? null : to.toLocalDate()));
54	        }, sheetId);
55	        for (Person person : found) {
56	            person.setHolds(new java.util.ArrayList<>(holds.getOrDefault(person.getId(), List.of())));
57	        }
58	        return found;
59	    }
60	
61	    /** Fills in each person's dated grades and the sheet's today (the grade in force on it is shown). */
62	    private List<Person> withGrades(String sheetId, List<Person> found) {
63	        if (found.isEmpty()) {
64	            return found;
65	        }
66	        java.time.LocalDate today = sheets.today(sheetId);
67	        java.util.Map<Long, java.util.Map<java.time.LocalDate, String>> grades = new java.util.HashMap<>();
68	        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ? ORDER BY seq", rs -> {
69	            java.sql.Date from = rs.getDate("from_date");
70	            grades.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.HashMap<>())
71	                    .put(from == null ? Person.BEGINNING : from.toLocalDate(), rs.getString("grade"));
72	        }, sheetId);
73	        withHolds(sheetId, found);
74	        for (Person person : found) {
75	            person.setGrades(grades.getOrDefault(person.getId(), java.util.Map.of()));
76	            person.setToday(today);
77	        }
78	        return found;
79	    }
80	
81	    /** Writes the grade the person's edit recorded, replacing any recorded from the same date. */
82	    private void writeRecordedGrade(Person person) {
83	        java.util.Map.Entry<java.time.LocalDate, String> recorded = person.getRecordedGrade();
84	        if (recorded == null) {
85	            return;
86	        }
87	        java.sql.Date from = recorded.getKey().equals(Person.BEGINNING) ? null : java.sql.Date.valueOf(recorded.getKey());
88	        if (from == null) {
89	            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date IS NULL",
90	                    person.getSheetId(), person.getId());
91	        } else {
92	            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date = ?",
93	                    person.getSheetId(), person.getId(), from);
94	        }
95	        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
96	                person.getSheetId(), person.getId(), from, recorded.getValue());
97	        jdbc.update("INSERT INTO grade_history (sheet_id, person_id, set_on, from_date, grade) VALUES (?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?)",
98	                person.getSheetId(), person.getId(), person.getSheetId(), from, recorded.getValue());
99	        person.clearRecordedGrade();
100	    }
101	
102	    /** Records the person's name, own terms and contact as they now stand in their history, dated the sheet's today. */
103	    private void writeHistory(Person person) {
104	        jdbc.update("INSERT INTO person_history (sheet_id, person_id, set_on, name, terms, contact) VALUES (?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?, ?)",
105	                person.getSheetId(), person.getId(), person.getSheetId(), person.getName(), person.getTerms(), person.getContact());
106	    }
107	
108	    /** The sheet's people in the order they were added. */
109	    public List<Person> list(String sheetId) {
110	        return withGrades(sheetId, withAliases(sheetId, withPatrons(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? ORDER BY id", ROW, sheetId))));
111	    }
112	
113	    /** Fills in each person's patrons (ids in the order named, names sorted). */
114	    private List<Person> withPatrons(String sheetId, List<Person> found) {
115	        if (found.isEmpty()) {
116	            return found;
117	        }
118	        java.util.Map<Long, java.util.List<Long>> ids = new java.util.HashMap<>();
119	        java.util.Map<Long, java.util.List<String>> names = new java.util.HashMap<>();
120	        jdbc.query("SELECT pp.person_id, pp.patron_id, p.name FROM person_patron pp"
121	                + " JOIN person p ON p.sheet_id = pp.sheet_id AND p.id = pp.patron_id"
122	                + " WHERE pp.sheet_id = ? ORDER BY pp.seq", rs -> {
123	                    long person = rs.getLong("person_id");
124	                    ids.computeIfAbsent(person, k -> new java.util.ArrayList<>()).add(rs.getLong("patron_id"));
125	                    names.computeIfAbsent(person, k -> new java.util.ArrayList<>()).add(rs.getString("name"));
126	                }, sheetId);
127	        for (Person person : found) {
128	            java.util.List<String> sorted = new java.util.ArrayList<>(names.getOrDefault(person.getId(), List.of()));
129	            sorted.sort(BY_NAME);
130	            person.setPatrons(new java.util.ArrayList<>(ids.getOrDefault(person.getId(), List.of())), sorted);
131	        }
132	        return found;
133	    }
134	
135	    /** Fills in each person's aliases, sorted as names are compared. */
136	    private List<Person> withAliases(String sheetId, List<Person> found) {
137	        if (found.isEmpty()) {
138	            return found;
139	        }
140	        java.util.Map<Long, java.util.List<String>> aliases = new java.util.HashMap<>();
141	        jdbc.query("SELECT person_id, alias FROM person_alias WHERE sheet_id = ? ORDER BY seq",
142	                rs -> {
143	                    aliases.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.ArrayList<>()).add(rs.getString("alias"));
144	                }, sheetId);
145	        for (Person person : found) {
146	            java.util.List<String> sorted = new java.util.ArrayList<>(aliases.getOrDefault(person.getId(), List.of()));
147	            sorted.sort(BY_NAME);
148	            person.setAliases(sorted);
149	        }
150	        return found;
151	    }
152	
153	    /** Records the alias as one of the person's. The person's version is left as it is. */
154	    public void addAlias(Person person, String alias) {
155	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, set_on) VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
156	                person.getSheetId(), person.getId(), alias, person.getSheetId());
157	        person.getAliases().add(alias);
158	        person.getAliases().sort(BY_NAME);
159	    }
160	
161	    /** Records the patron as one of the person's patrons. The person's version is left as it is. */
162	    public void addPatron(Person person, Person patron) {
163	        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, set_on) VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
164	                person.getSheetId(), person.getId(), patron.getId(), person.getSheetId());
165	        person.getPatronIds().add(patron.getId());
166	        person.getPatronNames().add(patron.getName());
167	        person.getPatronNames().sort(BY_NAME);
168	    }
169	
170	    public Person find(String sheetId, long id) {
171	        List<Person> found = withGrades(sheetId, withAliases(sheetId, withPatrons(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND id = ?", ROW, sheetId, id))));
172	        return found.isEmpty() ? null : found.get(0);
173	    }
174	
175	    /** The person on the sheet with this name or alias, compared without regard to case or outer spaces; null when none. */
176	    public Person findByName(String sheetId, String name) {
177	        List<Person> found = withGrades(sheetId, withAliases(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?)) ORDER BY id",
178	                ROW, sheetId, name)));
179	        if (found.isEmpty()) {
180	            found = withGrades(sheetId, withAliases(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND id IN"
181	                    + " (SELECT person_id FROM person_alias WHERE sheet_id = ? AND LOWER(TRIM(alias)) = LOWER(TRIM(?))) ORDER BY id",
182	                    ROW, sheetId, sheetId, name)));
183	        }
184	        return found.isEmpty() ? null : found.get(0);
185	    }
186	
187	    /** Whether another person on the sheet already has this name, or anyone on the sheet has it as an alias,
188	     *  compared without regard to case. */
189	    public boolean nameTaken(String sheetId, String name, Long exceptId) {
190	        Integer count = jdbc.queryForObject(
191	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?))"
192	                        + (exceptId == null ? "" : " AND id <> " + exceptId.longValue()),
193	                Integer.class, sheetId, name);
194	        Integer aliases = jdbc.queryForObject(
195	                "SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND LOWER(TRIM(alias)) = LOWER(TRIM(?))",
196	                Integer.class, sheetId, name);
197	        return (count != null && count > 0) || (aliases != null && aliases > 0);
198	    }
199	
200	    /** Whether another person on the sheet already has this contact. */
201	    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
202	        Integer count = jdbc.queryForObject(
203	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ?"
204	                        + (exceptId == null ? "" : " AND id <> " + exceptId.longValue()),
205	                Integer.class, sheetId, contact);
206	        return count != null && count > 0;
207	    }
208	
209	    public Person add(String sheetId, String name, String grade) {
210	        return add(sheetId, name, grade, null, null);
211	    }
212	
213	    /** Adds a person with their own terms in days (null for none) and contact (null for none). */
214	    public Person add(String sheetId, String name, String grade, Integer terms, String contact) {
215	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
216	        jdbc.update(con -> {
217	            PreparedStatement ps = con.prepareStatement(
218	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, added_on) VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
219	                    Statement.RETURN_GENERATED_KEYS);
220	            ps.setString(1, sheetId);
221	            ps.setString(2, name);
222	            ps.setString(3, grade);
223	            ps.setObject(4, terms, java.sql.Types.INTEGER);
224	            ps.setString(5, contact);
225	            ps.setString(6, sheetId);
226	            return ps;
227	        }, keys);
228	        Person person = new Person(keys.getKey().longValue(), sheetId, name, grade);
229	        person.setTerms(terms);
230	        person.setContact(contact);
231	        writeHistory(person);
232	        // The first grade a person is given applies from the beginning of time.
233	        person.recordGrade(Person.BEGINNING, grade);
234	        writeRecordedGrade(person);
235	        person.setToday(sheets.today(sheetId));
236	        return person;
237	    }
238	
239	    /** Records a statement taken for the person: one more, with its due-total and date. The person's
240	     *  version is left as it is — a statement is not an edit. */
241	    public void saveStatement(Person person) {
242	        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE sheet_id = ? AND id = ?",
243	                person.getStatementCount(), person.getStatedTotal(),
244	                person.getStatementDate() == null ? null : java.sql.Date.valueOf(person.getStatementDate()),
245	                person.getSheetId(), person.getId());
246	    }
247	
248	    /** Records a statement taken for the person in their statement history. */
249	    public void addStatement(Person person) {
250	        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date, set_on) VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
251	                person.getSheetId(), person.getId(), person.getStatedTotal(),
252	                person.getStatementDate() == null ? null : java.sql.Date.valueOf(person.getStatementDate()), person.getSheetId());
253	    }
254	
255	    /** Marks the person's last statement cancelled in their history (kept, dated, for the as-of view) and sets the person's statement to the one
256	     *  before it (no due-total or date when there is none, or it is not known). The count goes down by one. */
257	    public void cancelStatement(Person person) {
258	        List<Long> last = jdbc.query("SELECT seq FROM person_statement WHERE sheet_id = ? AND person_id = ? AND NOT cancelled ORDER BY seq DESC LIMIT 1",
259	                (rs, i) -> rs.getLong(1), person.getSheetId(), person.getId());
260	        if (!last.isEmpty()) {
261	            jdbc.update("UPDATE person_statement SET cancelled = TRUE, cancelled_on = (SELECT today FROM sheet WHERE id = ?) WHERE seq = ?",
262	                    person.getSheetId(), last.get(0));
263	        }
264	        person.setStatementCount(person.getStatementCount() - 1);
265	        person.setStatedTotal(null);
266	        person.setStatementDate(null);
267	        jdbc.query("SELECT stated_total, statement_date FROM person_statement WHERE sheet_id = ? AND person_id = ? AND NOT cancelled ORDER BY seq DESC LIMIT 1",
268	                rs -> {
269	                    person.setStatedTotal(rs.getBigDecimal("stated_total"));
270	                    java.sql.Date date = rs.getDate("statement_date");
271	                    person.setStatementDate(date == null ? null : date.toLocalDate());
272	                }, person.getSheetId(), person.getId());
273	        saveStatement(person);
274	    }
275	
276	    /** Records the person's retirement date. The person's version is left as it is — retiring is
277	     *  not an edit of the person form. */
278	    public void saveRetired(Person person) {
279	        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?",
280	                person.getRetiredFrom() == null ? null : java.sql.Date.valueOf(person.getRetiredFrom()),
281	                person.getSheetId(), person.getId());
282	        jdbc.update("INSERT INTO retire_history (sheet_id, person_id, set_on, retired_from) VALUES (?, ?, (SELECT today FROM sheet WHERE id = ?), ?)",
283	                person.getSheetId(), person.getId(), person.getSheetId(),
284	                person.getRetiredFrom() == null ? null : java.sql.Date.valueOf(person.getRetiredFrom()));
285	    }
286	
287	    /** Adds a hold to the person. The person's version is left as it is — holding is not an edit of
288	     *  the person form. */
289	    public void addHold(Person person, Person.Hold hold) {
290	        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, set_on) VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
291	                person.getSheetId(), person.getId(), java.sql.Date.valueOf(hold.from()),
292	                hold.to() == null ? null : java.sql.Date.valueOf(hold.to()), person.getSheetId());
293	        person.getHolds().add(hold);
294	    }
295	
296	    /** Saves the person over the version it was loaded at, moving it on by one, with any grade the
297	     *  edit recorded; false (nothing written) when someone else has saved the person since. */
298	    public boolean save(Person person) {
299	        int updated = jdbc.update(
300	                "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
301	                person.getName(), person.getTerms(), person.getContact(), person.getSheetId(), person.getId(), person.getVersion());
302	        if (updated == 0) {
303	            return false;
304	        }
305	        writeRecordedGrade(person);
306	        writeHistory(person);
307	        person.setVersion(person.getVersion() + 1);
308	        return true;
309	    }
310	}
