    seq       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    user_name VARCHAR(200) NOT NULL,
    UNIQUE (sheet_id, person_id, user_name)
);
-- A steward's delegation of the steward role to a user for a from-date and a to-date, inclusive, by the sheet's
-- today: while the sheet's today is inside the range the user acts as a steward, and the audit lines of their
-- changes end with for=<the steward who delegated>. Kept in the order given (seq).
CREATE TABLE sheet_delegation (
    seq          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(200) NOT NULL,
    user_name    VARCHAR(200) NOT NULL,
    from_date    DATE         NOT NULL,
    to_date      DATE         NOT NULL,
    delegated_by VARCHAR(200) NOT NULL
);
-- A person's claims. Listed newest first (id is assigned in the order they were added).
-- amount is 0.00 or more with at most two decimals; claim_date defaults to the sheet's today.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)  NOT NULL,
    person_id  BIGINT        NOT NULL,
    amount     DECIMAL(14,2) NOT NULL,
    claim_date DATE          NOT NULL,
    note       VARCHAR(2000) NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, person_id, id);
-- A steward archives the sheet: everything on it stays visible and every change to it is refused. Not undone.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
-- A person's own terms in days; null for none (their grade's terms, else the sheet's, apply).
ALTER TABLE person ADD COLUMN terms INT;
-- The user whose open editor locks the claim for everyone else; null when unlocked.
-- Released when that editor is saved or cancelled, and on every claim of the sheet when its today changes.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(200);
-- A period can be soft-closed: its due-total (closed_total) and each person's figure for it are fixed, but
-- claims dated inside it can still be added and changed. A claim added while its period is soft-closed is a
-- late entry.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- Each statement taken for a person, in the order taken: its due-total (null when n/a) and date. The
-- person's last statement can be cancelled, and the row then shows the one before it (or nothing).
-- A person's last statement taken before this history was kept is carried over; any before it are not
-- known, so cancelling it shows nothing.
CREATE TABLE person_statement (
    seq            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(200) NOT NULL,
    person_id      BIGINT       NOT NULL,
    stated_total   DECIMAL(14,2),
    statement_date DATE
);
INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date)
    SELECT sheet_id, id, stated_total, statement_date FROM person WHERE statement_count > 0;
-- History kept so a statement can be taken as of a past date: every change that moves a figure is recorded
-- with the sheet's today when it was made (set_on). The store as it stood at the end of a date is every change
-- made while the sheet's today was on or before it, the latest of each winning. A NULL set_on is a value carried
-- over from before this history was kept: it counts as of any date.

-- The sheet's today when the person was added; NULL when added before this was kept.
ALTER TABLE person ADD COLUMN added_on DATE;

-- Each claim's figure-moving columns after each change to them, in the order made.
CREATE TABLE claim_history (
    seq            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(200)  NOT NULL,
    claim_id       BIGINT        NOT NULL,
    set_on         DATE,
    person_id      BIGINT        NOT NULL,
    amount         DECIMAL(14,2) NOT NULL,
    claim_date     DATE          NOT NULL,
    status         VARCHAR(20)   NOT NULL,
    settled_due    DECIMAL(14,2),
    stated         BOOLEAN       NOT NULL,
    stated_due     DECIMAL(14,2),
    due_by         DATE,
    deferred_until DATE,
    corrects       VARCHAR(100)
);
CREATE INDEX claim_history_sheet ON claim_history (sheet_id, claim_id, seq);
INSERT INTO claim_history (sheet_id, claim_id, set_on, person_id, amount, claim_date, status, settled_due, stated,
        stated_due, due_by, deferred_until, corrects)
    SELECT sheet_id, id, NULL, person_id, amount, claim_date, status, settled_due, stated, stated_due, due_by,
        deferred_until, corrects FROM claim;

-- Each rate set, in the order set (a later one from the same grade and from-date replaces it).
CREATE TABLE rate_history (
    seq       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    set_on    DATE,
    grade     CHAR(1)      NOT NULL,
    rate      DECIMAL(6,2) NOT NULL,
    from_date DATE,
    to_date   DATE
);
INSERT INTO rate_history (sheet_id, set_on, grade, rate, from_date, to_date)
    SELECT sheet_id, NULL, grade, rate, from_date, to_date FROM rate;

-- Each dated setting recorded, in the order recorded (a later one from the same key and from-date replaces it).
CREATE TABLE setting_history (
    seq           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(200)  NOT NULL,
    set_on        DATE,
    setting_key   VARCHAR(40)   NOT NULL,
    from_date     DATE          NOT NULL,
    setting_value DECIMAL(12,2)
);
INSERT INTO setting_history (sheet_id, set_on, setting_key, from_date, setting_value)
    SELECT sheet_id, NULL, setting_key, from_date, setting_value FROM sheet_setting;

-- Each policy date set (NULL: blank), in the order set.
CREATE TABLE policy_history (
    seq         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(200) NOT NULL,
    set_on      DATE,
    policy_date DATE
);
INSERT INTO policy_history (sheet_id, set_on, policy_date) SELECT id, NULL, policy_date FROM sheet WHERE policy_date IS NOT NULL;

-- Each grade recorded for a person, in the order recorded (a later one from the same from-date replaces it).
CREATE TABLE grade_history (
    seq       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    set_on    DATE,
    from_date DATE,
    grade     CHAR(1)      NOT NULL
);
INSERT INTO grade_history (sheet_id, person_id, set_on, from_date, grade)
    SELECT sheet_id, person_id, NULL, from_date, grade FROM person_grade ORDER BY seq;

-- The sheet's today when each hold was added.
ALTER TABLE person_hold ADD COLUMN set_on DATE;

-- Each retirement date recorded for a person, in the order recorded.
CREATE TABLE retire_history (
    seq          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(200) NOT NULL,
    person_id    BIGINT       NOT NULL,
    set_on       DATE,
    retired_from DATE
);
INSERT INTO retire_history (sheet_id, person_id, set_on, retired_from)
    SELECT sheet_id, id, NULL, retired_from FROM person WHERE retired_from IS NOT NULL;
-- History kept so the whole screen can be shown as of a past date (see V45): what V45 left out is recorded here,
-- each change dated the sheet's today when it was made (set_on). A NULL set_on is a value carried over from before
-- this history was kept: it counts as of any date.

-- The rest of what a claim's row shows, after each change to it.
ALTER TABLE claim_history ADD COLUMN claim_number VARCHAR(220);
ALTER TABLE claim_history ADD COLUMN opened_by    VARCHAR(255);
ALTER TABLE claim_history ADD COLUMN note         VARCHAR(2000);
ALTER TABLE claim_history ADD COLUMN proofs       INT;
ALTER TABLE claim_history ADD COLUMN split_from   VARCHAR(64);
ALTER TABLE claim_history ADD COLUMN late_entry   BOOLEAN;
UPDATE claim_history h SET (claim_number, opened_by, note, proofs, split_from, late_entry) =
    (SELECT c.claim_number, c.opened_by, c.note, c.proofs, c.split_from, c.late_entry FROM claim c
        WHERE c.sheet_id = h.sheet_id AND c.id = h.claim_id);

-- Each name and own terms recorded for a person, in the order recorded.
CREATE TABLE person_history (
    seq       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL,
    person_id BIGINT        NOT NULL,
    set_on    DATE,
    name      VARCHAR(2000) NOT NULL,
    terms     INT
);
INSERT INTO person_history (sheet_id, person_id, set_on, name, terms) SELECT sheet_id, id, NULL, name, terms FROM person;

-- The sheet's today when each statement was taken, and when it was cancelled (a cancelled one is kept, marked).
ALTER TABLE person_statement ADD COLUMN set_on DATE;
ALTER TABLE person_statement ADD COLUMN cancelled BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE person_statement ADD COLUMN cancelled_on DATE;

-- The sheet's today when each patron was named.
ALTER TABLE person_patron ADD COLUMN set_on DATE;

-- Each start and stop of a watch, in the order made.
CREATE TABLE watch_history (
    seq       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    user_name VARCHAR(200) NOT NULL,
