          </li>
        ))}
      </ul>
      <SummaryPanel people={people} today={today} totalOf={totalOf} isActive={isActive} statusCount={statusCount} voidReasonCount={voidReasonCount} />
      </PersonSelection>
    </ClaimSelection>
  );
}
